CREATE TABLE payment_proofs(id BINARY(16) NOT NULL PRIMARY KEY,order_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,tenant_id BINARY(16) NOT NULL,storage_key VARCHAR(255) NOT NULL,filename VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,checksum CHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,submitted_at TIMESTAMP(6) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,CONSTRAINT uk_proof_idempotency UNIQUE(tenant_id,user_id,idempotency_key));
